payload.template:
{{ define "zabbix.default.payload" }}{
  "jsonrpc": "2.0",
  "method": "history.push",
  "params": [
    {{ range $index, $alert := .Alerts }}{{ if $index }},{{ end }}
    {"itemid": {{ $alert.Labels.zabbix_itemid }}, "value": "{{ $alert.ValueString }}"}
    {{ end }}
  ],
  "id": 1
}
{{ end }}
